// ======= CONFIG =======
// DAILY_CAP override: if set above 0 it replaces the auto ramp below. Set to 0 to use the ramp.
const DAILY_CAP = 0;
// START_DATE: first day of outreach. The ramp is based on whole weeks since this date.
const START_DATE = '2026-09-24';
// TEST_EMAIL: set to an email address to run in test mode. Keep in sync with the
// TEST_EMAIL constant at the top of this workflow file. Leave as an empty string for normal runs.
const TEST_EMAIL = "";
// ======================

// Auto ramp: week 1 = 5/day, week 2 = 10, week 3 = 15, week 4+ = 20, hard max 25.
function dailyCap() {
  if (DAILY_CAP > 0) return DAILY_CAP;
  const start = new Date(START_DATE + 'T00:00:00').getTime();
  const weeks = Math.max(0, Math.floor((Date.now() - start) / (7 * 24 * 60 * 60 * 1000)));
  return Math.min(25, 5 * Math.min(4, weeks + 1));
}
const CAP = dailyCap();

const rows = $input.all();
const now = Date.now();
const DAY_MS = 24 * 60 * 60 * 1000;

function daysSince(dateStr) {
  if (!dateStr) return Infinity;
  const t = new Date(dateStr).getTime();
  if (isNaN(t)) return Infinity;
  return (now - t) / DAY_MS;
}

const due = [];
for (const item of rows) {
  const j = item.json;
  const status = (j.status == null ? '' : String(j.status)).trim().toLowerCase();
  const email = (j.email == null ? '' : String(j.email)).trim();
  if (!email) continue; // skip leads with no email
  if (status === 'replied' || status === 'unsub' || status === 'done' || status === 'invalid') continue; // never touch these

  let step = 0;
  if (status === '') step = 1;
  else if (status === 'sent_1' && daysSince(j.last_sent) >= 3) step = 2;
  else if (status === 'sent_2' && daysSince(j.last_sent) >= 4) step = 3;

  if (step > 0) {
    due.push({ json: { ...j, step } });
  }
  if (due.length >= CAP) break;
}

// Test mode: output exactly one item — the first due lead with email replaced by TEST_EMAIL.
if (TEST_EMAIL && due.length > 0) {
  const first = due[0].json;
  return [{ json: { ...first, email: TEST_EMAIL, is_test: true } }];
}

return due;

const staticData = $getWorkflowStaticData('global');
const outcomes = Array.isArray(staticData.outcomes) ? staticData.outcomes : [];
staticData.outcomes = [];

const sent = outcomes.filter((o) => o.result === 'sent');
const skipped = outcomes.filter((o) => o.result !== 'sent');

const lines = [];
lines.push('Sent ' + sent.length + ' outreach email(s) today:');
for (const o of sent) {
  lines.push('- ' + o.business_name + ' <' + o.email + '> step ' + o.step);
}
if (skipped.length > 0) {
  lines.push('');
  lines.push('Skipped:');
  for (const o of skipped) {
    lines.push('- ' + o.business_name + ' <' + o.email + '>: ' + o.skip_reason);
  }
}

return [{ json: {
  subject: 'RLD outreach: ' + sent.length + ' sent today',
  body: lines.join(String.fromCharCode(10)),
} }];

// Basic email validation. MX check happens in the next node (HTTP to dns.google).
const lead = $('Loop One Lead at a Time').item.json;
const email = String(lead.email || '').trim().toLowerCase();
const today = new Date().toISOString().slice(0, 10);

function invalid(reason) {
  return { ...lead, invalid_email: true, new_status: 'invalid', skip_reason: reason, today };
}

const FORMAT = /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/;
if (!FORMAT.test(email)) return invalid('bad email format');

const local = email.split('@')[0];
const domain = email.split('@')[1] || '';
const BAD_LOCAL = ['noreply', 'no-reply', 'donotreply', 'abuse', 'postmaster', 'mailer-daemon'];
for (const b of BAD_LOCAL) {
  if (local.startsWith(b)) return invalid('non-personal address (' + b + ')');
}
const BAD_DOMAIN = ['facebook.com', 'example.com', 'mailinator.com', 'guerrillamail.com', 'tempmail.com', '10minutemail.com', 'yopmail.com'];
if (BAD_DOMAIN.indexOf(domain) !== -1) return invalid('blocked or disposable domain (' + domain + ')');

return { ...lead, email_domain: domain, invalid_email: false, today };

// Grade the lead's website from the fetch and PageSpeed results.
const lead = $('Has Website').item.json;
const site = $('Fetch Website').item.json || {};
const ps = $('Check PageSpeed').item.json || {};

const problems = [];

// 1. Request failed
const siteFailed = !!site.error || site.statusCode == null || Number(site.statusCode) >= 400;
if (siteFailed) problems.push('website is down or unreachable');

// 2. Not HTTPS
const url = String(lead.website || '');
if (!/^https:\/\//i.test(url)) problems.push('site is not on HTTPS');

const html = typeof site.body === 'string' ? site.body : (typeof site.data === 'string' ? site.data : '');

// 3. No viewport meta tag
if (!siteFailed && html) {
  if (!/<meta[^>]+name=["']viewport["']/i.test(html)) problems.push('not mobile friendly (no viewport meta tag)');
}

// 4. Copyright year 2+ years old
if (html) {
  const m = html.match(/(?:copyright|&copy;|©)[^0-9]{0,20}((?:19|20)\d{2})/i);
  if (m) {
    const year = parseInt(m[1], 10);
    if (year < new Date().getFullYear() - 2) problems.push('site has not been updated since ' + year);
  }
}

// 5. Mobile performance score under 50
if (!ps.error) {
  const score = ps.lighthouseResult && ps.lighthouseResult.categories && ps.lighthouseResult.categories.performance
    ? Math.round(ps.lighthouseResult.categories.performance.score * 100)
    : null;
  if (score != null && score < 50) problems.push('slow mobile site (performance score ' + score + '/100)');
}

const site_status = problems.length > 0 ? 'bad' : 'good';
const site_notes = problems.length > 0 ? problems.join('; ') : 'Site loads fine, HTTPS, mobile friendly, decent speed.';

return { ...lead, site_status, site_notes };

