// Parse the model JSON, strip em/en dashes, append footer, run the quality check.
const lead = $('Loop One Lead at a Time').item.json;

let text = '';
const content = $json.content;
if (Array.isArray(content)) {
  const block = content.find((c) => c && c.type === 'text');
  text = block && block.text ? block.text : '';
}
if (!text && typeof $json.merged_response === 'string') {
  text = $json.merged_response;
}

// strip markdown fences defensively
const FENCE = String.fromCharCode(96, 96, 96);
if (text.startsWith(FENCE)) {
  const firstNl = text.indexOf(String.fromCharCode(10));
  text = firstNl === -1 ? '' : text.slice(firstNl + 1);
  const lastFence = text.lastIndexOf(FENCE);
  if (lastFence !== -1) text = text.slice(0, lastFence);
  text = text.trim();
}

// Escape control characters inside quoted strings so JSON.parse survives raw newlines.
function sanitizeJson(str) {
  const BACKSLASH = 92, QUOTE = 34, LF = 10, CR = 13, TAB = 9;
  let out = '';
  let inString = false;
  let escaped = false;
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (escaped) { out += str[i]; escaped = false; continue; }
    if (code === BACKSLASH) { out += str[i]; escaped = true; continue; }
    if (code === QUOTE) { inString = !inString; out += str[i]; continue; }
    if (inString && code === LF) { out += String.fromCharCode(92) + 'n'; continue; }
    if (inString && code === CR) { out += String.fromCharCode(92) + 'r'; continue; }
    if (inString && code === TAB) { out += String.fromCharCode(92) + 't'; continue; }
    out += str[i];
  }
  return out;
}

let parsed = null;
try {
  parsed = JSON.parse(text);
} catch (e) {
  try {
    parsed = JSON.parse(sanitizeJson(text));
  } catch (e2) {
    const m = text.match(/{[sS]*}/);
    if (m) {
      try { parsed = JSON.parse(sanitizeJson(m[0])); } catch (e3) { parsed = null; }
    }
  }
}

const BANNED = ['free money', 'guarantee', 'act now', 'limited time', 'click here', '100%', 'risk free', 'winner', 'urgent', 'cash', 'discount', 'offer expires'];
const DASHES = [String.fromCharCode(0x2014), String.fromCharCode(0x2013), String.fromCharCode(0x2212), '-'];

function wordCount(s) { return String(s).trim().split(/\s+/).filter(Boolean).length; }

function checkQuality(subject, body) {
  const fails = [];
  if (/https?:\/\/|www\.|\.com\b|\.net\b|\.org\b|\.io\b/i.test(body)) fails.push('body contains a URL or link');
  for (const d of DASHES) {
    if (body.indexOf(d) !== -1) { fails.push('body contains a dash character'); break; }
  }
  const lower = body.toLowerCase();
  for (const w of BANNED) {
    if (lower.indexOf(w) !== -1) fails.push('body contains banned phrase: ' + w);
  }
  if (wordCount(body) > 90) fails.push('body is over 90 words');
  if (wordCount(subject) > 6) fails.push('subject is over 6 words');
  return fails;
}

const isRegen = lead.regen === true;
let quality_failures = [];

if (!parsed || !parsed.subject || !parsed.body) {
  quality_failures = ['model output could not be parsed'];
} else {
  quality_failures = checkQuality(String(parsed.subject), String(parsed.body));
}

if (quality_failures.length > 0 && !isRegen) {
  // First failure: flag for one regeneration pass.
  return {
    needs_regen: true,
    quality_failures: quality_failures.join('; '),
    subject: parsed && parsed.subject ? String(parsed.subject) : '',
    body: parsed && parsed.body ? String(parsed.body) : '',
    is_test: lead.is_test === true,
  };
}

const step = lead.step;
const today = new Date().toISOString().slice(0, 10);

if (!parsed || !parsed.subject || !parsed.body || quality_failures.length > 0) {
  // Second failure (or regen still broken): skip the lead with copy_failed.
  return {
    copy_failed: true,
    skip_reason: 'copy_failed',
    email: lead.email,
    business_name: lead.business_name,
    row_number: lead.row_number,
    new_status: lead.status || '',
    today,
    step,
    is_test: lead.is_test === true,
  };
}

// Strip dashes defensively even on a passing draft.
const EM_DASH = String.fromCharCode(0x2014);
const EN_DASH = String.fromCharCode(0x2013);
const stripDashes = (s) => String(s)
  .split(EM_DASH).join(',')
  .split(EN_DASH).join(',')
  .replace(/,{2,}/g, ',');

const subject = stripDashes(parsed.subject).trim();
let body = stripDashes(parsed.body).trim();

// Collapse single line breaks inside paragraphs into spaces; keep blank lines between paragraphs.
const CR = String.fromCharCode(13);
const LF = String.fromCharCode(10);
const SPC = String.fromCharCode(32);
const TAB = String.fromCharCode(9);
const CR_RE = new RegExp(CR, 'g');
const SINGLE_LF_RE = new RegExp('([^' + LF + '])' + LF + '(?!' + LF + ')', 'g');
const MULTI_SPACE_RE = new RegExp('[' + SPC + TAB + ']{2,}', 'g');
const MULTI_LF_RE = new RegExp(LF + '{3,}', 'g');
body = body
  .replace(CR_RE, '')
  .replace(SINGLE_LF_RE, '$1 ')
  .replace(MULTI_SPACE_RE, ' ')
  .replace(MULTI_LF_RE, LF + LF)
  .trim();

// Remove any sign-off Claude wrote at the end (bare 'Ron', 'Ron Lenser Digital', or a phone number).
const SIGNOFF_NAMES = ['ron', 'ron lenser digital'];
const isSignoffLine = (l) => {
  const t = String(l).trim().toLowerCase();
  if (!t) return false;
  if (SIGNOFF_NAMES.indexOf(t) !== -1) return true;
  const digits = t.replace(/[^0-9]/g, '');
  const PHONE_CHARS_RE = new RegExp('^[+()0-9][0-9() .' + String.fromCharCode(92) + '-x]*$');
  if (digits.length >= 7 && PHONE_CHARS_RE.test(t)) return true;
  return false;
};
const bodyLines = body.split(LF);
while (bodyLines.length > 0) {
  const last = bodyLines[bodyLines.length - 1];
  if (last.trim() === '' || isSignoffLine(last)) { bodyLines.pop(); continue; }
  break;
}
body = bodyLines.join(LF).trim();

// Always append the exact signature after a blank line.
body += LF + LF + 'Ron' + LF + 'Ron Lenser Digital' + LF + 'YOUR PHONE';

// Then the existing footer after a blank line.
body += LF + LF + "Not interested? Reply stop and I won't email again.";
body += LF + "Ron Lenser Digital, YOUR MAILING ADDRESS";

// Build the HTML version: escape & < >, paragraphs on double newlines,
// single newlines inside a paragraph become <br>, paragraphs joined by spacer divs.
const escapeHtml = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const paragraphs = body.split(LF + LF).map((p) => p.trim()).filter((p) => p !== '');
const body_html = paragraphs
  .map((p) => '<div>' + escapeHtml(p).split(LF).join('<br>') + '</div>')
  .join('<div><br></div>');

const newStatus = step === 1 ? 'sent_1' : step === 2 ? 'sent_2' : 'done';

return {
  subject,
  body,
  body_html,
  email: lead.email,
  business_name: lead.business_name,
  row_number: lead.row_number,
  new_status: newStatus,
  today,
  step,
  message_id: lead.message_id || '',
  site_status: lead.site_status || '',
  is_test: lead.is_test === true,
};

// Record one line for the daily summary in the workflow static data.
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.outcomes)) staticData.outcomes = [];

const lead = $('Loop One Lead at a Time').item.json;
const input = $json;

let entry = null;
if (input.copy_failed === true) {
  entry = { business_name: input.business_name || lead.business_name, email: input.email || lead.email, step: input.step || lead.step, result: 'skipped', skip_reason: 'copy_failed' };
} else if (lead.invalid_email === true || (input.error && !input.Answer)) {
  // invalid email or MX failure path
  const v = $('Validate Email').item.json;
  entry = { business_name: lead.business_name, email: lead.email, step: lead.step, result: 'skipped', skip_reason: v.skip_reason || 'no MX records for domain' };
} else if (input.id || input.threadId || lead.is_test === true) {
  // a Gmail send/reply response, or a test-run send (Is Test Run true branch passes Clean Email Output fields)
  entry = { business_name: lead.business_name, email: lead.email, step: lead.step, result: 'sent', skip_reason: '' };
} else {
  entry = { business_name: lead.business_name, email: lead.email, step: lead.step, result: 'skipped', skip_reason: 'unknown' };
}
staticData.outcomes.push(entry);
return entry;

